            let kind = LiftLoadKind(rawValue: String(kindName.dropFirst()))!
            let got = LiftPlates.rowLoad(kind: kind, weight: w, base: base, inventory: inventories[i])
            let label = "\(kindName) inventory #\(i) base \(base) weight \(w)"
            guard let expected else { XCTAssertNil(got, label); continue }
            guard let got else { XCTFail("nil for \(label)"); continue }
            XCTAssertEqual(got.kind, expected.0, label)
            XCTAssertEqual(got.barOnly, expected.1, label)
            XCTAssertEqual(got.underBar, expected.2, label)
            XCTAssertEqual(got.bar, expected.3, label)
            XCTAssertEqual(got.perSide, expected.4, accuracy: 1e-12, label)
            XCTAssertEqual(got.plates, expected.5, label)
            XCTAssertEqual(got.missing, expected.6, accuracy: 1e-12, label)
        }
    }

    func testPlateDeltaAgreesWithOpenGym() {
        let cases: [([Double], [Double], [Double], [Double])] = [
        ([25.0, 10.0, 5.0], [25.0, 15.0], [10.0, 5.0], [15.0]),
        ([], [20.0, 20.0], [], [20.0, 20.0]),
        ([20.0, 20.0], [], [20.0, 20.0], []),
        ([25.0, 25.0, 5.0], [25.0, 25.0, 5.0], [], []),
        ([20.0, 10.0, 10.0, 2.5], [20.0, 20.0, 1.25], [10.0, 10.0, 2.5], [20.0, 1.25]),
        ([45.0, 25.0, 10.0], [45.0, 45.0, 5.0], [25.0, 10.0], [45.0, 5.0]),
        ]
        for (a, b, strip, add) in cases {
            let d = LiftPlates.plateDelta(from: a, to: b)
            XCTAssertEqual(d.strip, strip, "\(a) -> \(b)")
            XCTAssertEqual(d.add, add, "\(a) -> \(b)")
        }
    }

    func testBarsAgreeWithOpenGym() {
        let cases: [(String, String, Double?, Bool)] = [
        ("barbell", ".kg", 20.0, true),
        ("barbell", ".lb", 45.0, true),
        ("olympic barbell", ".kg", 20.0, true),
        ("olympic barbell", ".lb", 45.0, true),
        ("ez barbell", ".kg", 10.0, true),
        ("ez barbell", ".lb", 25.0, true),
        ("smith machine", ".kg", 9.0, true),
        ("smith machine", ".lb", 20.0, true),
        ("trap bar", ".kg", 25.0, true),
        ("trap bar", ".lb", 55.0, true),
        ("dumbbell", ".kg", nil, false),
        ("dumbbell", ".lb", nil, false),
        ("cable", ".kg", nil, false),
        ("cable", ".lb", nil, false),
        ]
        for (eq, unit, weight, usesBar) in cases {
            XCTAssertEqual(LiftPlates.defaultBar(eq, unit: LiftPlateUnit(rawValue: String(unit.dropFirst()))!), weight, "\(eq) \(unit)")
            XCTAssertEqual(LiftPlates.usesBar(eq), usesBar, eq)
        }
    }

