        (4, 50.0, 25.0, nil, nil, [25.0], [25.0], 25.0),
        ]
        for (i, x, floor, up1, up2, around, aroundStrict, deload) in cases {
            let ws = lists[i], label = "list #\(i), \(x)"
            XCTAssertEqual(LiftPlates.ownedFloor(ws, x), floor, label)
            XCTAssertEqual(LiftPlates.ownedUp(ws, x, 1), up1, label)
            XCTAssertEqual(LiftPlates.ownedUp(ws, x, 2), up2, label)
            XCTAssertEqual(LiftPlates.ownedAround(x, ws, max: 30, strict: false), around, label)
            XCTAssertEqual(LiftPlates.ownedAround(x, ws, max: 30, strict: true), aroundStrict, label)
            XCTAssertEqual(LiftPlates.ownedDeload(ws, x, factor: 0.9), deload, label)
        }
    }

    func testCleanWeightsAgreesWithOpenGym() {
        let cases: [([Double], [Double])] = [
        ([3.0, 1.0, 2.0, 2.0, 0.0, -1.0, 5.0004, 10000.0], [1.0, 2.0, 3.0, 5.0]),
        ([], []),
        ([1.5, 1.5], [1.5]),
        ([0.0004, 7.0], [0.0, 7.0]),
        ]
        for (input, expected) in cases { XCTAssertEqual(LiftPlates.cleanWeights(input), expected, "\(input)") }
    }
}
